import csv
import json
import math
from collections import defaultdict
from datetime import datetime

# ── Read and parse the CSV ──────────────────────────────────────────────
rows = []
with open("/app/benchmark/data.csv", "r") as f:
    reader = csv.DictReader(f)
    for r in reader:
        d = datetime.strptime(r["Date"], "%Y-%m-%d")
        p = float(r["Crude_Oil_Price"])
        rows.append({"date": d, "price": p})

rows.sort(key=lambda x: x["date"])
prices = [r["price"] for r in rows]
dates = [r["date"].strftime("%Y-%m-%d") for r in rows]
n = len(rows)

# ── KPI 1: Overall Price Range ──────────────────────────────────────────
min_price = min(prices)
max_price = max(prices)
min_date = dates[prices.index(min_price)]
max_date = dates[prices.index(max_price)]
overall_range = max_price - min_price

# ── KPI 2: CAGR ─────────────────────────────────────────────────────────
first_price = prices[0]
last_price = prices[-1]
first_date_str = dates[0]
last_date_str = dates[-1]
years_elapsed = (rows[-1]["date"] - rows[0]["date"]).days / 365.25
cagr = ((last_price / first_price) ** (1 / years_elapsed) - 1) * 100

# ── KPI 3: Maximum MoM Change ───────────────────────────────────────────
mom_abs_changes = []
mom_pct_changes = []
mom_data = []
for i in range(1, n):
    abs_chg = prices[i] - prices[i-1]
    pct_chg = (abs_chg / prices[i-1]) * 100
    mom_abs_changes.append(abs_chg)
    mom_pct_changes.append(pct_chg)
    mom_data.append({
        "from_date": dates[i-1],
        "to_date": dates[i],
        "from_price": round(prices[i-1], 2),
        "to_price": round(prices[i], 2),
        "abs_change": round(abs_chg, 2),
        "pct_change": round(pct_chg, 2)
    })

max_mom_abs = max(mom_abs_changes, key=abs)
max_mom_pct = max(mom_pct_changes, key=abs)
max_mom_abs_idx = mom_abs_changes.index(max_mom_abs)
max_mom_pct_idx = mom_pct_changes.index(max_mom_pct)
max_mom_abs_entry = mom_data[max_mom_abs_idx]
max_mom_pct_entry = mom_data[max_mom_pct_idx]

# ── KPI 4: Decade with Highest Average Price ────────────────────────────
decade_groups = defaultdict(list)
for r in rows:
    decade = (r["date"].year // 10) * 10
    decade_groups[decade].append(r["price"])

decade_stats = {}
for dec in sorted(decade_groups.keys()):
    vals = decade_groups[dec]
    decade_stats[str(dec)] = {
        "avg": round(sum(vals) / len(vals), 2),
        "min": round(min(vals), 2),
        "max": round(max(vals), 2),
        "std": round(stdev(vals) if len(vals) > 1 else 0, 2),
        "count": len(vals),
        "range": round(max(vals) - min(vals), 2)
    }

highest_avg_decade = max(decade_stats.items(), key=lambda x: x[1]["avg"])

# ── KPI 5: Overall Standard Deviation ───────────────────────────────────
mean_price = sum(prices) / n
variance = sum((p - mean_price) ** 2 for p in prices) / n
overall_std = math.sqrt(variance)

# Helper for stdev (sample std for decade stats)
def stdev(vals):
    m = sum(vals) / len(vals)
    return math.sqrt(sum((v - m) ** 2 for v in vals) / (len(vals) - 1))

# ── Year-over-Year changes ──────────────────────────────────────────────
yoy_data = []
for i in range(12, n):
    pct = ((prices[i] - prices[i-12]) / prices[i-12]) * 100
    yoy_data.append({
        "date": dates[i],
        "pct_change": round(pct, 2),
        "price": round(prices[i], 2),
        "price_12m_ago": round(prices[i-12], 2)
    })

# ── Annual averages ─────────────────────────────────────────────────────
annual_avg = defaultdict(list)
for r in rows:
    annual_avg[r["date"].year].append(r["price"])
annual_stats = {}
for yr in sorted(annual_avg.keys()):
    vals = annual_avg[yr]
    annual_stats[yr] = {
        "avg": round(sum(vals) / len(vals), 2),
        "min": round(min(vals), 2),
        "max": round(max(vals), 2)
    }

# ── Percentiles ─────────────────────────────────────────────────────────
sorted_prices = sorted(prices)
def percentile(pct):
    k = (len(sorted_prices) - 1) * pct / 100
    f = math.floor(k)
    c = math.ceil(k)
    if f == c:
        return sorted_prices[int(k)]
    return sorted_prices[f] + (sorted_prices[c] - sorted_prices[f]) * (k - f)

p10 = round(percentile(10), 2)
p25 = round(percentile(25), 2)
p50 = round(percentile(50), 2)
p75 = round(percentile(75), 2)
p90 = round(percentile(90), 2)

# ── Key events mapping ──────────────────────────────────────────────────
key_events = [
    {"date": "1973-10-01", "label": "1973 Oil Embargo", "price": 4.10},
    {"date": "1974-01-01", "label": "Price quadruples post-embargo", "price": 13.0},
    {"date": "1979-05-01", "label": "Iranian Revolution spike", "price": 33.5},
    {"date": "1980-11-01", "label": "Iran-Iraq War peak", "price": 40.3},
    {"date": "1986-07-01", "label": "1986 Oil Price Collapse", "price": 9.62},
    {"date": "1990-10-01", "label": "Gulf War spike", "price": 34.5},
    {"date": "1998-12-01", "label": "Asian Financial Crisis low", "price": 10.41},
    {"date": "2008-07-01", "label": "All-time high ($132.83)", "price": 132.83},
    {"date": "2008-12-01", "label": "GFC collapse", "price": 41.34},
    {"date": "2011-04-01", "label": "Arab Spring peak", "price": 116.24},
    {"date": "2014-12-01", "label": "Shale oil price collapse", "price": 60.70},
    {"date": "2016-01-01", "label": "Post-shale trough", "price": 29.78},
    {"date": "2020-04-01", "label": "COVID-19 demand shock", "price": 21.04},
    {"date": "2022-03-01", "label": "Ukraine invasion spike", "price": 112.40},
    {"date": "2026-03-01", "label": "Latest observation ($87.84)", "price": 87.84},
]

# ── Monthly prices for Chart.js (lightweight) ───────────────────────────
chart_monthly = [{"x": dates[i], "y": round(prices[i], 2)} for i in range(n)]
# Sample to every 3rd point for very large datasets if needed - but 675 is fine

# ── Decade bar chart data ───────────────────────────────────────────────
decade_bar_labels = []
decade_bar_avgs = []
decade_bar_mins = []
decade_bar_maxs = []
for dec in sorted(decade_groups.keys()):
    s = decade_stats[str(dec)]
    label = f"{dec}s"
    decade_bar_labels.append(label)
    decade_bar_avgs.append(s["avg"])
    decade_bar_mins.append(s["min"])
    decade_bar_maxs.append(s["max"])

# ── Annual averages for chart ───────────────────────────────────────────
annual_years = sorted(annual_stats.keys())
annual_avgs = [annual_stats[y]["avg"] for y in annual_years]

# ── Top 10 MoM changes ──────────────────────────────────────────────────
top_mom_abs = sorted(mom_data, key=lambda x: abs(x["abs_change"]), reverse=True)[:10]
top_mom_pct = sorted(mom_data, key=lambda x: abs(x["pct_change"]), reverse=True)[:10]

# ── Build HTML report ───────────────────────────────────────────────────
# Prepare data payload as JSON
data_payload = {
    "kpi_overall_range": round(overall_range, 2),
    "kpi_min_price": round(min_price, 2),
    "kpi_max_price": round(max_price, 2),
    "kpi_min_date": min_date,
    "kpi_max_date": max_date,
    "kpi_cagr": round(cagr, 2),
    "kpi_first_price": round(first_price, 2),
    "kpi_last_price": round(last_price, 2),
    "kpi_first_date": first_date_str,
    "kpi_last_date": last_date_str,
    "kpi_years_elapsed": round(years_elapsed, 1),
    "kpi_max_mom_abs": round(max_mom_abs, 2),
    "kpi_max_mom_abs_from": max_mom_abs_entry["from_date"],
    "kpi_max_mom_abs_to": max_mom_abs_entry["to_date"],
    "kpi_max_mom_abs_from_price": max_mom_abs_entry["from_price"],
    "kpi_max_mom_abs_to_price": max_mom_abs_entry["to_price"],
    "kpi_max_mom_pct": round(max_mom_pct, 2),
    "kpi_max_mom_pct_from": max_mom_pct_entry["from_date"],
    "kpi_max_mom_pct_to": max_mom_pct_entry["to_date"],
    "kpi_max_mom_pct_from_price": max_mom_pct_entry["from_price"],
    "kpi_max_mom_pct_to_price": max_mom_pct_entry["to_price"],
    "kpi_highest_avg_decade": highest_avg_decade[0],
    "kpi_highest_avg_decade_val": highest_avg_decade[1]["avg"],
    "kpi_overall_std": round(overall_std, 2),
    "kpi_overall_mean": round(mean_price, 2),
    "kpi_overall_median": p50,
    "kpi_p10": p10,
    "kpi_p25": p25,
    "kpi_p75": p75,
    "kpi_p90": p90,
    "n_rows": n,
    "chart_monthly": json.dumps(chart_monthly),
    "decade_bar_labels": json.dumps(decade_bar_labels),
    "decade_bar_avgs": json.dumps(decade_bar_avgs),
    "decade_bar_mins": json.dumps(decade_bar_mins),
    "decade_bar_maxs": json.dumps(decade_bar_maxs),
    "annual_years": json.dumps(annual_years),
    "annual_avgs": json.dumps(annual_avgs),
    "top_mom_abs": top_mom_abs,
    "top_mom_pct": top_mom_pct,
    "decade_stats": json.dumps({k: v for k, v in sorted(decade_stats.items())}),
    "key_events": json.dumps(key_events),
    "yoy_data": json.dumps(yoy_data),
    "mom_pct_series": json.dumps([round(v, 2) for v in mom_pct_changes]),
    "mom_dates_series": json.dumps(dates[1:]),
    "annual_stats": json.dumps(annual_stats)
}

# Embed the data payload as JSON in the HTML
data_json = json.dumps(data_payload)

html = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
