<div class="report-container">

<!-- ═══════════ HEADER ═══════════ -->
<header class="report-header">
  <h1>Global Crude Oil Price Trends: A Historical Analysis (1970–2026)</h1>
  <p class="subtitle">A comprehensive trend analysis of monthly crude oil prices spanning over five decades, identifying key price regimes, shocks, and long-term patterns.</p>
  <div class="meta">
    <span>Dataset: {n} monthly observations</span>
    <span>Range: {first_date_str} – {last_date_str}</span>
    <span>Analysis Date: May 2026</span>
  </div>
</header>

<!-- ═══════════ SECTION 1: EXECUTIVE OVERVIEW ═══════════ -->
