rows = []
with open("/app/benchmark/data.csv", "r") as f:
    reader = csv.DictReader(f)
    for r in reader:
        d = datetime.strptime(r["Date"], "%Y-%m-%d")
        p = float(r["Crude_Oil_Price"])
        rows.append({"date": d, "price": p})

rows.sort(key=lambda x: x["date"])
prices = [r["price"] for r in rows]
dates = [r["date"].strftime("%Y-%m-%d") for r in rows]
n = len(rows)

# ── KPI 1: Overall Price Range ──────────────────────────────────────────
min_price = min(prices)
max_price = max(prices)
min_date = dates[prices.index(min_price)]
max_date = dates[prices.index(max_price)]
overall_range = max_price - min_price

# ── KPI 2: CAGR ─────────────────────────────────────────────────────────
first_price = prices[0]
last_price = prices[-1]
first_date_str = dates[0]
last_date_str = dates[-1]
years_elapsed = (rows[-1]["date"] - rows[0]["date"]).days / 365.25
cagr = ((last_price / first_price) ** (1 / years_elapsed) - 1) * 100

# ── KPI 3: Maximum MoM Change ───────────────────────────────────────────
mom_abs_changes = []
mom_pct_changes = []
mom_data = []
for i in range(1, n):
    abs_chg = prices[i] - prices[i-1]
    pct_chg = (abs_chg / prices[i-1]) * 100
    mom_abs_changes.append(abs_chg)
    mom_pct_changes.append(pct_chg)
    mom_data.append({
        "from_date": dates[i-1],
        "to_date": dates[i],
        "from_price": round(prices[i-1], 2),
        "to_price": round(prices[i], 2),
        "abs_change": round(abs_chg, 2),
        "pct_change": round(pct_chg, 2)
    })

max_mom_abs = max(mom_abs_changes, key=abs)
max_mom_pct = max(mom_pct_changes, key=abs)
max_mom_abs_idx = mom_abs_changes.index(max_mom_abs)
max_mom_pct_idx = mom_pct_changes.index(max_mom_pct)
