import csv
import json
import math
from collections import defaultdict
from datetime import datetime

# ── Read and parse the CSV ──────────────────────────────────────────────
rows = []
with open("/app/benchmark/data.csv", "r") as f:
    reader = csv.DictReader(f)
    for r in reader:
        d = datetime.strptime(r["Date"], "%Y-%m-%d")
        p = float(r["Crude_Oil_Price"])
        rows.append({"date": d, "price": p})

rows.sort(key=lambda x: x["date"])
prices = [r["price"] for r in rows]
dates = [r["date"].strftime("%Y-%m-%d") for r in rows]
n = len(rows)

# ── KPI 1: Overall Price Range ──────────────────────────────────────────
min_price = min(prices)
max_price = max(prices)
min_date = dates[prices.index(min_price)]
max_date = dates[prices.index(max_price)]
overall_range = max_price - min_price

# ── KPI 2: CAGR ─────────────────────────────────────────────────────────
first_price = prices[0]
last_price = prices[-1]
first_date_str = dates[0]
last_date_str = dates[-1]
years_elapsed = (rows[-1]["date"] - rows[0]["date"]).days / 365.25
cagr = ((last_price / first_price) ** (1 / years_elapsed) - 1) * 100

# ── KPI 3: Maximum MoM Change ───────────────────────────────────────────
mom_abs_changes = []
mom_pct_changes = []
mom_data = []
for i in range(1, n):
    abs_chg = prices[i] - prices[i-1]
    pct_chg = (abs_chg / prices[i-1]) * 100
    mom_abs_changes.append(abs_chg)
    mom_pct_changes.append(pct_chg)
    mom_data.append({
        "from_date": dates[i-1],
        "to_date": dates[i],
        "from_price": round(prices[i-1], 2),
        "to_price": round(prices[i], 2),
        "abs_change": round(abs_chg, 2),
        "pct_change": round(pct_chg, 2)
    })

max_mom_abs = max(mom_abs_changes, key=abs)
max_mom_pct = max(mom_pct_changes, key=abs)
max_mom_abs_idx = mom_abs_changes.index(max_mom_abs)
max_mom_pct_idx = mom_pct_changes.index(max_mom_pct)
max_mom_abs_entry = mom_data[max_mom_abs_idx]
max_mom_pct_entry = mom_data[max_mom_pct_idx]

# ── KPI 4: Decade with Highest Average Price ────────────────────────────
decade_groups = defaultdict(list)
for r in rows:
    decade = (r["date"].year // 10) * 10
    decade_groups[decade].append(r["price"])

decade_stats = {}
for dec in sorted(decade_groups.keys()):
    vals = decade_groups[dec]
    decade_stats[str(dec)] = {
        "avg": round(sum(vals) / len(vals), 2),
        "min": round(min(vals), 2),
        "max": round(max(vals), 2),
        "std": round(stdev(vals) if len(vals) > 1 else 0, 2),
        "count": len(vals),
        "range": round(max(vals) - min(vals), 2)
    }

highest_avg_decade = max(decade_stats.items(), key=lambda x: x[1]["avg"])

# ── KPI 5: Overall Standard Deviation ───────────────────────────────────
mean_price = sum(prices) / n
variance = sum((p - mean_price) ** 2 for p in prices) / n
overall_std = math.sqrt(variance)

# Helper for stdev (sample std for decade stats)
def stdev(vals):
    m = sum(vals) / len(vals)
    return math.sqrt(sum((v - m) ** 2 for v in vals) / (len(vals) - 1))

# ── Year-over-Year changes ──────────────────────────────────────────────
yoy_data = []
for i in range(12, n):
    pct = ((prices[i] - prices[i-12]) / prices[i-12]) * 100
    yoy_data.append({
        "date": dates[i],
        "pct_change": round(pct, 2),
        "price": round(prices[i], 2),
        "price_12m_ago": round(prices[i-12], 2)
    })

# ── Annual averages ─────────────────────────────────────────────────────
annual_avg = defaultdict(list)
for r in rows:
    annual_avg[r["date"].year].append(r["price"])
annual_stats = {}
for yr in sorted(annual_avg.keys()):
    vals = annual_avg[yr]
    annual_stats[yr] = {
        "avg": round(sum(vals) / len(vals), 2),
        "min": round(min(vals), 2),
        "max": round(max(vals), 2)
    }

# ── Percentiles ─────────────────────────────────────────────────────────
sorted_prices = sorted(prices)
def percentile(pct):
    k = (len(sorted_prices) - 1) * pct / 100
    f = math.floor(k)
    c = math.ceil(k)
    if f == c:
        return sorted_prices[int(k)]
    return sorted_prices[f] + (sorted_prices[c] - sorted_prices[f]) * (k - f)

