  const bins = new Array(binCount).fill(0);
  const binLabels = [];

  for (let i = 0; i < binCount; i++) {{
    const low = minP + i * binWidth;
    const high = low + binWidth;
    binLabels.push(`$${{low.toFixed(1)}}`);
    for (const p of prices) {{
      if (p >= low && (p < high || (i === binCount - 1 && p <= high))) bins[i]++;
    }}
  }}

  new Chart(document.getElementById('chartHistogram'), {{
    type: 'bar',
    data: {{
      labels: binLabels,
      datasets: [{{
        label: 'Frequency',
        data: bins,
        backgroundColor: 'rgba(30,96,145,0.7)',
        borderColor: '#1e6091',
        borderWidth: 0.5,
        borderRadius: 1,
        barPercentage: 1,
        categoryPercentage: 1
      }}]
    }},
    options: {{
      responsive: true,
      maintainAspectRatio: false,
      plugins: {{
        tooltip: {{ callbacks: {{ label: ctx => `${{ctx.parsed.y}} months` }} }},
        legend: {{ display: false }}
      }},
      scales: {{
        x: {{
          title: {{ display: true, text: 'Price (USD/bbl)', color: '#777' }},
          ticks: {{ maxTicksLimit: 15, callback: v => v }}
        }},
        y: {{
          title: {{ display: true, text: 'Number of Months', color: '#777' }}
        }}
      }}
    }}
  }});
}})();

